module multi_booth_8bit(
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] p,
    output reg rdy
);

    reg [15:0] multiplier;
    reg [15:0] multiplicand;
    reg [4:0] ctr;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            p <= 16'b0;
            ctr <= 5'b0;
            multiplier <= {{8{a[7]}}, a};
            multiplicand <= {{8{b[7]}}, b};
            rdy <= 1'b0;
        end else begin
            if (ctr < 16) begin
                multiplicand <= multiplicand << 1;
                if (multiplier[ctr] == 1'b1) begin
                    p <= p + multiplicand;
                end
                ctr <= ctr + 1;
            end else begin
                rdy <= 1'b1;
            end
        end
    end
endmodule

