module lfsr (
	input clk,
	input resetn,
	output reg [13:0] q);

always @(posedge clk or negedge resetn) begin
	if (~resetn)
		q <= 14'b00000000000001;
	else
		q <= {q[12:0], q[13] ^ q[4]};
end

endmodule

