  reg [0:0] mem_to_reg, mem_write, branch, alu_src, reg_dst, reg_write, jump;
  reg [1:0] alu_ctrl;

  always @(*) begin
    case(op)

      6'b000010: begin
        jump = 1;
        reg_write = 0;
        mem_write = 0;
    	end

      6'b000000:
        case(funct)




          6'b100000: begin
            reg_write = 1;
