    input [7:0] in,
    input clk,            // Added clk input as it was missing
    output reg [7:0] out
);reg [7:0] stage1_out;
reg [7:0] stage2_out;

// Stage 1: Invert the input using a constant value generator
always @(*) begin
    stage1_out = ~in;
end

