Design a synchronous FIFO (First-In, First-Out) memory buffer that uses a 14-depth storage array to hold 14-bit wide data inputs. The FIFO supports data writing when there is available space and data reading when there is data present, controlled by the clock and an active-low reset signal. The module features dedicated pointers for reading and writing operations, which advance on each clock cycle when appropriate conditions are met, and maintains a count of the current number of entries. The output provides the data from the FIFO based on the read pointer, ensuring proper data flow management in data communication applications.
module top_module(
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);

code:
module top_module(
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);output reg [31:0] readdata; // Change output to reg type
  input [1:0] address;
  input clk;
  input [13:0] in_port;
  input reset_n;

  reg [13:0] fifo [0:13];
  reg [3:0] write_ptr;
  reg [3:0] read_ptr;
  reg [3:0] count;

  // Write enable signal
  wire we;
  assign we = (count < 14);

  // Read enable signal
  wire re;
  assign re = (count > 0);

  // Write pointer incrementer
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) 
      write_ptr <= 0; // Initialize write_ptr on reset
    else if (we) 
      write_ptr <= write_ptr + 1;
  end

  // Read pointer incrementer
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) 
      read_ptr <= 0; // Initialize read_ptr on reset
    else if (re) 
      read_ptr <= read_ptr + 1;
  end

  // Count incrementer/decrementer
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) 
      count <= 0; // Initialize count on reset
    else if (we) 
      count <= count + 1;
    else if (re) 
      count <= count - 1;
  end

  // Write data to FIFO
  always @(posedge clk or negedge reset_n) begin
    if (we && reset_n)
      fifo[write_ptr] <= in_port;
  end

  // Read data from FIFO
  always @(posedge clk or negedge reset_n) begin
    if (re && reset_n)
      readdata <= {18'b0, fifo[read_ptr]}; // Adjust size to 32 bits
    else if (!re && reset_n)
      readdata <= 0;
  end

endmodule

