description:
Design a 4-to-1 binary encoder that converts a 16-bit input signal into a 4-bit binary output. The output is generated only when the enable signal is active. The encoder identifies which of the specific bits in the input (from 2^1 to 2^15) is high and produces a corresponding binary value from 1 to 15, while outputting zero if none of the specified bits are set or when the enable signal is inactive.
module top_module(
binary_out , 
encoder_in , 
enable       
);

code:
module top_module(
binary_out , 
encoder_in , 
enable       
);output [3:0] binary_out  ;

input  enable ; 
input [15:0] encoder_in ; 

reg [3:0] binary_out ;  

always @ (enable or encoder_in)
 begin 
   binary_out = 0; 
   if (enable) begin
     if (encoder_in == 16'h0002) begin
      binary_out = 1;
     end  if (encoder_in == 16'h0004) begin 
      binary_out = 2; 
     end  if (encoder_in == 16'h0008) begin 
      binary_out = 3; 
     end  if (encoder_in == 16'h0010) begin 
      binary_out = 4; 
     end  if (encoder_in == 16'h0020) begin 
      binary_out = 5; 
     end  if (encoder_in == 16'h0040) begin 
      binary_out = 6; 
     end  if (encoder_in == 16'h0080) begin 
      binary_out = 7; 
     end  if (encoder_in == 16'h0100) begin 
      binary_out = 8; 
     end  if (encoder_in == 16'h0200) begin 
      binary_out = 9; 
     end if (encoder_in == 16'h0400) begin 
      binary_out = 10; 
     end  if (encoder_in == 16'h0800) begin 
      binary_out = 11; 
     end  if (encoder_in == 16'h1000) begin
      binary_out = 12; 
     end  if (encoder_in == 16'h2000) begin 
      binary_out = 13;
     end  if (encoder_in == 16'h4000) begin 
      binary_out = 14; 
     end if (encoder_in == 16'h8000) begin 
      binary_out = 15; 
     end
  end
end

endmodule

