module counter8bit_sync_reset (
    input clk,
    input rst,
    output [7:0] q
);

    reg [7:0] q_reg;

    always @(posedge clk) begin
        if (rst)
            q_reg <= 8'b00000000;
        else
            q_reg <= q_reg + 1;
    end

    assign q = q_reg;

endmodule

