    reg valid_reg;
    reg ready_reg;

    always @(posedge din_valid) begin
        if (din_ready) begin
            data_reg <= din_data;
            last_reg <= din_last;
            valid_reg <= 1'b1;
            ready_reg <= 1'b0;
        end
    end

