        if (dout_valid) begin
            valid_reg <= 1'b0;
            ready_reg <= 1'b1;
        end
    end

    assign dout_data = data_reg;
    assign dout_last = last_reg;
    assign dout_valid = valid_reg;
    assign din_ready = ready_reg;

endmodule

