module shift_reg(
  input clk,
  input load,
  input shift,
  input [31:0] data_in,
  output reg [31:0] data_out
);

  always @(posedge clk) begin
    if (load)
      data_out <= data_in;
    else if (shift)
      data_out <= {1'b0, data_out[31:1]};
  end

endmodule

