Implement the Verilog module based on the following description.
We want to create a 4-bit priority encoder that:

// (1) takes a 4-bit input 'in',
// (2) outputs a 2-bit binary encoded value 'out' representing the position of the highest-order '1' in 'in',
// (3) outputs '00' if all bits in 'in' are '0'.

module top_module(
    input wire [3:0] in,
    output reg [1:0] out
);

code:
module top_module(
    input wire [3:0] in,
    output reg [1:0] out
);

    always @(*) begin
        casex (in)
            4'b1xxx: out = 2'b11;
            4'b01xx: out = 2'b10;
            4'b001x: out = 2'b01;
            4'b0001: out = 2'b00;
            default: out = 2'b00;
        endcase
    end

endmodule

