description:
Design a finite state machine (FSM) with 4 distinct states that toggles its output signals between all zeroes and all ones based on the current state. Upon reset, the FSM initializes to STATE_00, which outputs zero and transitions to STATE_01. In STATE_01, the output is all ones, transitioning to STATE_10 where the output returns to zero, followed by STATE_11 which again outputs all ones before cycling back to STATE_00. The FSM operates on a clock signal and incorporates asynchronous reset functionality, making it suitable for applications requiring a repeating binary signal pattern.
module top_module(
  input clk,
  input rst,
  // other input signals required by the FSM
  output reg [n-1:0] out
);

code:
module top_module(
  input clk,
  input rst,
  // other input signals required by the FSM
  output reg [n-1:0] out
);parameter n = 2; // number of output signals
parameter m = 4; // number of states in the FSM

// Define the states using state encoding compression
parameter STATE_00 = 2'b00;
parameter STATE_01 = 2'b01;
parameter STATE_10 = 2'b10;
parameter STATE_11 = 2'b11;

// Define the transitions between states
reg [1:0] state, next_state;
always @(posedge clk) begin
  if (rst) begin
    state <= STATE_00;
  end else begin
    state <= next_state;
  end
end

// Define the output signals for each state
always @(*) begin
  case (state)
    STATE_00: begin
      out = {n{1'b0}};
      next_state = STATE_01;
    end
    STATE_01: begin
      out = {n{1'b1}};
      next_state = STATE_10;
    end
    STATE_10: begin
      out = {n{1'b0}};
      next_state = STATE_11;
    end
    STATE_11: begin
      out = {n{1'b1}};
      next_state = STATE_00;
    end
