module top_module_tb;

    // Testbench signals (sequential circuit)
    reg [22:0] address_in;
    reg clk;
    reg [15:0] data_in;
    reg rd;
    reg reset;
    reg sel_akiko;
    wire [15:0] data_out;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .address_in(address_in),
        .clk(clk),
        .data_in(data_in),
        .rd(rd),
        .reset(reset),
        .sel_akiko(sel_akiko),
        .data_out(data_out)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset = 1;
        address_in = 0;
        data_in = 0;
        rd = 0;
        sel_akiko = 0;
        @(posedge clk);
        #2 reset = 0;
        @(posedge clk);
        #2;
    end
        endtask
    task write_word;

        input [15:0] data;
        begin
            address_in = 23'h5C001C;
            sel_akiko = 1;
            rd = 0;
            data_in = data;
            @(posedge clk);
            #2;
            sel_akiko = 0;
            @(posedge clk);
            #2;
        end
        endtask

    task read_word;

        begin
            address_in = 23'h5C001C;
            sel_akiko = 1;
            rd = 1;
            @(posedge clk);
            #2;
        end
        endtask

