        end

        for (i = 0; i < 8; i = i + 1) begin
            read_word();
        end

        #1;


        check_outputs(16'h1007);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        $display("Testcase %03d: Address mismatch prevents write", test_num);
        reset_dut();
        address_in = 23'h5C001D;
        sel_akiko = 1;
