        #1;

        check_outputs(16'h0000);
    end
        endtask

    task testcase004;

    begin
        test_num = 4;
        $display("Testcase %03d: sel_akiko low prevents read", test_num);
        reset_dut();
        write_word(16'hBEEF);

        address_in = 23'h5C001C;
        sel_akiko = 0;
        rd = 1;
        @(posedge clk);
