module top_module(
  input clk, // Added input for the clock signal
  input [N-1:0] dpos,
  input [N-1:0] cpos,
  output reg [M-1:0] ctrl // Changed output to reg type
);parameter N = 8; // width of desired position and current position signals
parameter M = 8; // width of control signal

reg [M-1:0] pwm;
reg [M-1:0] pwm_counter = 0; // Initialized pwm_counter
reg [M-1:0] error;
reg [M-1:0] prev_error = 0; // Initialized prev_error
reg [M-1:0] integral = 0; // Initialized integral
reg [M-1:0] derivative;

parameter Kp = 1; // proportional gain
parameter Ki = 1; // integral gain (modified to be an integer for simplicity)
parameter Kd = 1; // derivative gain (modified to be an integer for simplicity)

always @ (posedge clk) begin
  error <= dpos - cpos;
  integral <= integral + error;
  derivative <= error - prev_error;
  prev_error <= error;
  pwm <= Kp * error + Ki * integral + Kd * derivative;

  if (pwm_counter >= pwm) begin
    ctrl <= 1;
    pwm_counter <= 0;
  end else begin
    ctrl <= 0;
    pwm_counter <= pwm_counter + 1;
  end
end

endmodule

