description:
Design a 16-bit Gray code counter. It increments its value on each rising edge of the clock signal, while maintaining a reset capability that initializes the output to 0 when the reset signal is asserted low. The next state is determined by performing a bitwise XOR operation on the current state with a left-shifted version of itself, ensuring the output transitions occur in Gray code format, where only one bit changes at a time.
module top_module(
  input                clk,
  input                rst_n,
  output reg  [15:0]   Q
);

code:
module top_module(
  input                clk,
  input                rst_n,
  output reg  [15:0]   Q
);reg [15:0] next_state;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      Q <= 16'b0;
      next_state <= 16'b0;
    end
    else begin
      Q <= next_state;
      next_state <= Q ^ ({Q[14:0],1'b0});
    end
  end

endmodule

module top_module(
	Clk,
	Reset,
	In,
	Out
    );parameter RED_COEF = 14617;
parameter NTRU_Q = 4591;
parameter P_WIDTH = 16;

input					Clk;
input					Reset;
input		[P_WIDTH*2-1 : 0]	In;
output reg	[P_WIDTH-1 : 0]		Out;

reg		[P_WIDTH*2-1 : 0]	In_reg;

reg 		[31 : 0]	d;

wire 		[31 : 0]	e;

reg 		[31 : 0]	f;

wire 		[31 : 0]	g;

always@(posedge Clk)
begin
	if(Reset)
		In_reg <= {P_WIDTH*2{1'b0}};
	else
		In_reg <= In;
end

always@(posedge Clk)
begin
	if(Reset)
		d <= 32'b0;
	else
		d <= (In>>12)*RED_COEF;
end

assign e = (d>>14)*NTRU_Q;

always@(posedge Clk)
begin
	if(Reset)
		f <= 32'b0;
	else
		f <= In_reg-e;
end

assign g = f[15:0];

always@(posedge Clk)
begin
	if(Reset)
		Out <= 16'b0;
	else if(g>=2*NTRU_Q)
		Out <= g-2*NTRU_Q;
	else if(g>=NTRU_Q)
		Out <= g-NTRU_Q;
	else
		Out <= g;
end
endmodule

