module top_module(
    aclr,
    clock,
    data0x,
    data1x,
    data2x,
    data3x,
    sel,
    result
);input aclr;
input clock;
input [7:0] data0x;
input [7:0] data1x;
input [7:0] data2x;
input [7:0] data3x;
input [1:0] sel;
output [7:0] result;

reg [7:0] selected_data;

always @(posedge clock or negedge aclr) begin
    if (!aclr) begin
        selected_data <= 8'b0;
    end else begin
        case (sel)
            2'b00: selected_data <= data0x;
            2'b01: selected_data <= data1x;
            2'b10: selected_data <= data2x;
            2'b11: selected_data <= data3x;
        endcase
    end
end

assign result = selected_data;

endmodule

