module top_module(
    input in,
    input [2:0] state,    // 3-bit one-hot current state
    output reg WAIT_next,
    output reg PROCESS_next,
    output reg COMPLETE_next,
    output reg out
 );parameter WAIT=0, PROCESS=1, COMPLETE=2;

