	assign PROCESS_next = state[WAIT]&in | state[PROCESS]&in | state[COMPLETE]&in;
	assign COMPLETE_next = state[PROCESS]&~in | state[COMPLETE]&~in;

	assign out = state[PROCESS];

endmodule

