description:
Design a clock divider that reduces the input clock frequency by a specified factor, defaulting to 5000. It counts the number of rising edges of the input clock (clkin) and toggles the output clock (clkout) whenever the counter reaches the set factor, effectively generating a lower frequency clock signal.
module top_module(
	input clkin,
	output clkout
	);

code:
module top_module(
	input clkin,
	output clkout
	);parameter factor = 5000;


	reg [31:0] counter = 1;
	reg temp_clk = 0;
	always @ (posedge(clkin))
	begin
		if (counter == factor)
		begin
			counter <= 1;
			temp_clk <= ~temp_clk;
		end
		else
			counter <= counter + 1;
	end
	assign clkout = temp_clk;
endmodule

