module xor_gate_pipe_128bit
(
    input clk,
    input rst_n,
    input i_en,
    input [127:0] xor_a,
    input [127:0] xor_b,
    output [127:0] result,
    output reg o_en
);

reg stage1;
reg stage2;
reg stage3;

reg [127:0] xor_a_ff1;
reg [127:0] xor_b_ff1;
reg [127:0] xor_a_ff2;
reg [127:0] xor_b_ff2;
reg [127:0] xor_a_ff3;
reg [127:0] xor_b_ff3;

reg [127:0] xor1;
reg [127:0] xor2;
reg [127:0] xor3;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1 <= 1'b0;
        stage2 <= 1'b0;
        stage3 <= 1'b0;
        o_en <= 1'b0;
    end else begin
        stage1 <= i_en;
        stage2 <= stage1;
        stage3 <= stage2;
        o_en <= stage3;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        xor_a_ff1 <= 128'd0;
        xor_b_ff1 <= 128'd0;
        xor_a_ff2 <= 128'd0;
        xor_b_ff2 <= 128'd0;
        xor_a_ff3 <= 128'd0;
        xor_b_ff3 <= 128'd0;
    end else if (i_en) begin
        xor_a_ff1 <= xor_a;
        xor_b_ff1 <= xor_b;
        xor_a_ff2 <= xor_a_ff1;
        xor_b_ff2 <= xor_b_ff1;
        xor_a_ff3 <= xor_a_ff2;
        xor_b_ff3 <= xor_b_ff2;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        xor1 <= 128'd0;
        xor2 <= 128'd0;
        xor3 <= 128'd0;
    end else if (stage1) begin
        xor1 <= xor_a_ff1 ^ xor_b_ff1;
        xor2 <= xor1;
        xor3 <= xor2;
    end
end

assign result = xor3;

endmodule

module decoder2to4 (
  input [1:0] bin,
  output reg [3:0] onehot
);

  always @(*) begin
    case (bin)
      2'b00: onehot = 4'b0001;
      2'b01: onehot = 4'b0010;
      2'b10: onehot = 4'b0100;
      2'b11: onehot = 4'b1000;
      default: onehot = 4'b0000;
    endcase
  end

endmodule

