module top_module(
    Q    ,
    Q_N  ,
    CLK  ,
    D    ,
    SET_B,
    RESET
);// Module ports
    output Q    ;
    output Q_N  ;
    input  CLK  ;
    input  D    ;
    input  SET_B;
    input  RESET;

    // Local signals
    wire buf_Q;
    wire SET  ;
    wire RST  ;

    //                           Delay       Name  Output  Other arguments
    not                                      not0 (SET   , SET_B          );
    not                                      not1 (RST   , RESET          );
    and                                      and0 (buf_Q , SET, RST       );
    // Use a behavioral description for the DFF if the specific DFF implementation is not defined
    reg dff_reg;
    always @(posedge CLK or negedge SET or negedge RESET) begin
        if (!RESET)
            dff_reg <= 1'b0;                // Active low reset
        else if (!SET)
            dff_reg <= 1'b1;                // Active low set
        else
            dff_reg <= D;                   // D input on the rising edge of CLK
    end
    assign Q = dff_reg;
    assign Q_N = ~dff_reg;

endmodule

